@page "/board"
@rendermode InteractiveServer
@using sv_edb6f26597ef4216ba723ed7d5af581d.Services
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Kanban Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Total</small><strong>@_allTasks.Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">To Do</small><strong>@GetColumnTasks("To Do").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">In Progress</small><strong>@GetColumnTasks("In Progress").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Done</small><strong>@GetColumnTasks("Done").Count</strong></div></div>
        <div class="col"><div class="card text-center p-2"><small class="text-muted">Overdue</small><strong class="text-danger">@_allTasks.Count(t => t.DueDate.Date < DateTime.Today)</strong></div></div>
    </div>

    <!-- Search -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Columns -->
    <div class="row g-3">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@tasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2 overflow-auto" style="max-height:60vh;">
                        @foreach (var task in tasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="mb-1 small text-muted">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (GetColumnIndex(column) > 0)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) - 1])">
                                                ← Move Left
                                            </button>
                                        }
                                        @if (GetColumnIndex(column) < _columns.Length - 1)
                                        {
                                            <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) + 1])">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_addingColumn == column)
                        {
                            <div class="card border-primary">
                                <div class="card-body p-2">
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Title"
                                               @bind="_newTitle" />
                                    </div>
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                               @bind="_newAssignee" />
                                    </div>
                                    <div class="mb-2">
                                        <select class="form-select form-select-sm" @bind="_newPriority">
                                            <option value="High">High</option>
                                            <option value="Medium">Medium</option>
                                            <option value="Low">Low</option>
                                        </select>
                                    </div>
                                    <div class="mb-2">
                                        <input type="date" class="form-control form-control-sm" @bind="_newDueDate" />
                                    </div>
                                    @if (_formError is not null)
                                    {
                                        <div class="text-danger small mb-1">@_formError</div>
                                    }
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm flex-fill"
                                                disabled="@_saving"
                                                @onclick="SaveNewTaskAsync">
                                            @(_saving ? "Saving…" : "Save")
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm flex-fill"
                                                disabled="@_saving"
                                                @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    @if (_addingColumn != column)
                    {
                        <div class="card-footer">
                            <button class="btn btn-outline-primary btn-sm w-100"
                                    @onclick="() => StartAdd(column)">
                                + Add Task
                            </button>
                        </div>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _errorMessage;
    private string _searchText = string.Empty;

    // Move state
    private int? _movingTaskId;

    // Add-task form state
    private string? _addingColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;
    private string? _formError;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _errorMessage = null;
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            tasks = tasks
                .Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
        return tasks;
    }

    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _movingTaskId = taskId;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = _allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private void StartAdd(string column)
    {
        _addingColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
        _formError = null;
    }

    private void CancelAdd()
    {
        _addingColumn = null;
        _formError = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
        {
            _formError = "Title is required.";
            return;
        }

        _saving = true;
        _formError = null;
        try
        {
            var created = await TaskService.CreateTaskAsync(
                _newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);

            // If the task was created with a different status than the column, update it
            if (created.Status != _addingColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingColumn!);
                created = created with { Status = _addingColumn! };
            }

            _allTasks.Add(created);
            _addingColumn = null;
        }
        catch (Exception ex)
        {
            _formError = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

